"use client"

import { useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { StoreProvider, useStore } from "@/lib/store"
import { SidebarProvider } from "@/components/ui/sidebar"
import { LayoutDashboard, Users, Plane, CreditCard, Search, Settings, FileText, LogOut, ChevronRight, PanelLeftClose, PanelLeftOpen } from "lucide-react"
import { Dashboard }      from "@/components/dashboard"
import { Clientes }       from "@/components/clientes"
import { Viagens }        from "@/components/viagens"
import { Pagamentos }     from "@/components/pagamentos"
import { PesquisaRapida } from "@/components/pesquisa-rapida"
import { Configuracoes }  from "@/components/configuracoes"
import { ThemeToggle }    from "@/components/theme-toggle"
import { Relatorio }      from "@/components/relatorio"
import { UpdateBanner }   from "@/components/update-banner"
import { FichaCliente }   from "@/components/ficha-cliente"


const LOGO_BASE64 = "data:image/png;base64,"

const navItems = [
  { id: "dashboard",     label: "Dashboard",     sublabel: "Visão geral",         icon: LayoutDashboard },
  { id: "viagens",       label: "Viagens",        sublabel: "Gerenciar excursões",      icon: Plane },
  { id: "clientes",      label: "Clientes",       sublabel: "Passageiros",          icon: Users },
  { id: "pagamentos",    label: "Pagamentos",     sublabel: "Financeiro",           icon: CreditCard },
  { id: "pesquisa",      label: "Pesquisa",       sublabel: "Busca rápida",         icon: Search },
  { id: "relatorios",    label: "Relatórios",     sublabel: "Exportar dados",       icon: FileText },
  { id: "configuracoes", label: "Configurações",  sublabel: "Sistema",              icon: Settings },
]

function useAuthGuard() {
  const router = useRouter()
  const [verified, setVerified] = useState(false)
  useEffect(() => {
    const user = sessionStorage.getItem("user")
    if (!user) router.replace("/login")
    else setVerified(true)
  }, [router])
  return verified
}

function AppLayout() {
  const { activeSection, setActiveSection } = useStore()
  const [collapsed, setCollapsed] = useState(false)
  const router = useRouter()

  async function handleLogout() {
    sessionStorage.removeItem("user")
    if (typeof window !== "undefined" && window.electronAPI?.clearSession) {
      await window.electronAPI.clearSession()
    }
    router.replace("/login")
  }

  const active = navItems.find(n => n.id === activeSection)

  return (
    <div className="flex h-screen w-full overflow-hidden bg-background">
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap');

        .gt-sidebar * { font-family: 'Outfit', sans-serif !important; }

        :root {
          --sb-bg:       #0b1120;
          --sb-border:   rgba(255,255,255,0.07);
          --sb-text:     rgba(180,192,210,0.75);
          --sb-active:   #f0f4ff;
          --sb-accent:   #3b82f6;
          --sb-hover:    rgba(255,255,255,0.04);
          --sb-icon-bg:  rgba(255,255,255,0.05);
          --sb-icon-act: rgba(59,130,246,0.2);
        }

        .gt-nav-item {
          display: flex;
          align-items: center;
          gap: 10px;
          padding: 8px 10px;
          cursor: pointer;
          border-radius: 10px;
          margin: 2px 8px;
          transition: background 140ms ease;
          position: relative;
        }
        .gt-nav-item:hover { background: var(--sb-hover); }
        .gt-nav-item.active { background: rgba(59,130,246,0.12); }
        .gt-nav-item.active::before {
          content: "";
          position: absolute;
          left: 0; top: 8px; bottom: 8px;
          width: 3px;
          background: var(--sb-accent);
          border-radius: 0 3px 3px 0;
        }

        .gt-icon-wrap {
          flex-shrink: 0;
          width: 32px; height: 32px;
          display: flex; align-items: center; justify-content: center;
          border-radius: 8px;
          background: var(--sb-icon-bg);
          transition: background 140ms;
        }
        .gt-nav-item.active .gt-icon-wrap {
          background: var(--sb-icon-act);
        }

        .gt-label-main {
          font-size: 13px;
          font-weight: 500;
          color: var(--sb-text);
          white-space: nowrap;
          transition: color 140ms;
        }
        .gt-nav-item.active .gt-label-main {
          color: var(--sb-active);
          font-weight: 600;
        }
        .gt-label-sub {
          font-size: 10.5px;
          font-weight: 400;
          color: rgba(180,192,210,0.4);
          white-space: nowrap;
        }

        .gt-divider {
          height: 1px;
          background: var(--sb-border);
          margin: 6px 16px;
        }

        .gt-collapse-btn {
          width: 26px; height: 26px;
          border-radius: 7px;
          border: 1px solid var(--sb-border);
          background: transparent;
          display: flex; align-items: center; justify-content: center;
          cursor: pointer;
          color: rgba(180,192,210,0.5);
          transition: all 140ms;
          flex-shrink: 0;
        }
        .gt-collapse-btn:hover {
          background: rgba(59,130,246,0.15);
          color: var(--sb-accent);
          border-color: rgba(59,130,246,0.3);
        }

        .gt-logout-btn {
          display: flex; align-items: center; gap: 8px;
          padding: 8px 10px;
          border-radius: 10px;
          border: none;
          background: transparent;
          cursor: pointer;
          color: rgba(180,192,210,0.55);
          font-size: 13px;
          font-weight: 500;
          font-family: 'Outfit', sans-serif !important;
          width: 100%;
          transition: all 140ms;
          white-space: nowrap;
        }
        .gt-logout-btn:hover {
          background: rgba(239,68,68,0.1);
          color: #f87171;
        }
        .gt-logout-btn-icon {
          width: 32px; height: 32px;
          display: flex; align-items: center; justify-content: center;
          border-radius: 8px;
          background: rgba(255,255,255,0.04);
          flex-shrink: 0;
          transition: background 140ms;
        }
        .gt-logout-btn:hover .gt-logout-btn-icon {
          background: rgba(239,68,68,0.15);
        }
      `}</style>

      <aside
        className="gt-sidebar"
        style={{
          width: collapsed ? "58px" : "216px",
          minWidth: collapsed ? "58px" : "216px",
          transition: "width 220ms cubic-bezier(0.4,0,0.2,1), min-width 220ms cubic-bezier(0.4,0,0.2,1)",
          display: "flex",
          flexDirection: "column",
          background: "var(--sb-bg)",
          borderRight: "1px solid var(--sb-border)",
          overflow: "hidden",
          position: "relative",
          zIndex: 10,
        }}
      >
        <div style={{
          padding: "14px 10px 12px",
          display: "flex",
          alignItems: "center",
          gap: 8,
          borderBottom: "1px solid var(--sb-border)",
          minHeight: 60,
        }}>
          <div style={{ width:34, height:34, flexShrink:0, display:"flex", alignItems:"center", justifyContent:"center" }}>
            <img src={LOGO_BASE64} alt="logo" style={{ width:32, height:32, objectFit:"contain" }} />
          </div>
          {!collapsed && (
            <div style={{ flex:1, overflow:"hidden", minWidth:0 }}>
              <div style={{
                fontSize: 15,
                fontWeight: 700,
                color: "#f0f4ff",
                letterSpacing: "0.01em",
                whiteSpace: "nowrap",
              }}>
                Gestor<span style={{ color:"#3b82f6" }}>Trip</span>
              </div>
              <div style={{
                fontSize: 10,
                fontWeight: 400,
                color: "rgba(180,192,210,0.4)",
                letterSpacing: "0.08em",
                textTransform: "uppercase",
                whiteSpace: "nowrap",
              }}>
                gestão de viagens
              </div>
            </div>
          )}
          <button
            className="gt-collapse-btn"
            onClick={() => setCollapsed(c => !c)}
            title={collapsed ? "Expandir menu" : "Recolher menu"}
          >
            {collapsed
              ? <PanelLeftOpen size={13} />
              : <PanelLeftClose size={13} />
            }
          </button>
        </div>

        <nav style={{ flex:1, paddingTop:8, paddingBottom:4, overflowY:"auto", overflowX:"hidden" }}>
          {navItems.slice(0, 4).map(item => (
            <div
              key={item.id}
              className={`gt-nav-item ${activeSection === item.id ? "active" : ""}`}
              onClick={() => setActiveSection(item.id)}
              title={collapsed ? item.label : undefined}
            >
              <div className="gt-icon-wrap">
                <item.icon
                  size={15}
                  style={{ color: activeSection === item.id ? "var(--sb-accent)" : "var(--sb-text)" }}
                />
              </div>
              {!collapsed && (
                <>
                  <div style={{ flex:1, overflow:"hidden", minWidth:0 }}>
                    <div className="gt-label-main">{item.label}</div>
                    <div className="gt-label-sub">{item.sublabel}</div>
                  </div>
                  {activeSection === item.id && (
                    <ChevronRight size={12} style={{ color:"var(--sb-accent)", flexShrink:0 }} />
                  )}
                </>
              )}
            </div>
          ))}

          <div className="gt-divider" />

          {navItems.slice(4).map(item => (
            <div
              key={item.id}
              className={`gt-nav-item ${activeSection === item.id ? "active" : ""}`}
              onClick={() => setActiveSection(item.id)}
              title={collapsed ? item.label : undefined}
            >
              <div className="gt-icon-wrap">
                <item.icon
                  size={15}
                  style={{ color: activeSection === item.id ? "var(--sb-accent)" : "var(--sb-text)" }}
                />
              </div>
              {!collapsed && (
                <>
                  <div style={{ flex:1, overflow:"hidden", minWidth:0 }}>
                    <div className="gt-label-main">{item.label}</div>
                    <div className="gt-label-sub">{item.sublabel}</div>
                  </div>
                  {activeSection === item.id && (
                    <ChevronRight size={12} style={{ color:"var(--sb-accent)", flexShrink:0 }} />
                  )}
                </>
              )}
            </div>
          ))}
        </nav>

        <div style={{
          borderTop: "1px solid var(--sb-border)",
          padding: "8px 8px 10px",
          display: "flex",
          flexDirection: "column",
          gap: 4,
        }}>
          <div style={{
            display: "flex",
            alignItems: "center",
            padding: "4px 2px",
          }}>
            <ThemeToggle variant="sidebar" />
          </div>

          <button
            className="gt-logout-btn"
            onClick={handleLogout}
            title={collapsed ? "Sair" : undefined}
          >
            <div className="gt-logout-btn-icon">
              <LogOut size={15} />
            </div>
            {!collapsed && <span>Sair</span>}
          </button>
        </div>
      </aside>

      <div style={{ flex:1, display:"flex", flexDirection:"column", overflow:"hidden", fontFamily:"'Outfit', sans-serif" }}>
        <header style={{
          height: 48,
          display: "flex",
          alignItems: "center",
          paddingLeft: 24,
          paddingRight: 20,
          borderBottom: "1px solid hsl(var(--border))",
          gap: 10,
          flexShrink: 0,
        }}>
          <div style={{ display:"flex", alignItems:"center", gap:6 }}>
            <span style={{
              fontSize: 14,
              fontWeight: 600,
              color: "hsl(var(--foreground))",
              fontFamily: "'Outfit', sans-serif",
            }}>
              {active?.label ?? ""}
            </span>
            {active?.sublabel && (
              <span style={{
                fontSize: 12,
                color: "hsl(var(--muted-foreground))",
                fontFamily: "'Outfit', sans-serif",
                fontWeight: 400,
              }}>
                — {active.sublabel}
              </span>
            )}
          </div>
        </header>

        <main style={{ flex:1, overflowY:"auto", padding:"22px 26px" }}>
          {activeSection === "dashboard"     && <Dashboard />}
          {activeSection === "clientes"      && <Clientes />}
          {activeSection === "viagens"       && <Viagens />}
          {activeSection === "pagamentos"    && <Pagamentos />}
          {activeSection === "pesquisa"      && <PesquisaRapida />}
          {activeSection === "relatorios"    && <Relatorio />}
          {activeSection === "configuracoes" && <Configuracoes />}
        </main>
      </div>

      <FichaCliente />
      <UpdateBanner />
    </div>
  )
}

function AppShell() {
  const verified = useAuthGuard()
  if (!verified) return null
  return (
    <SidebarProvider>
      <AppLayout />
    </SidebarProvider>
  )
}

export default function Page() {
  return (
    <StoreProvider>
      <AppShell />
    </StoreProvider>
  )
}